param([Parameter(Mandatory=$true)][string]$CsvPath,[Parameter(Mandatory=$true)][string]$OutPath,[string]$Variant='UNKNOWN',[string]$RuntimeSha256='')
$ErrorActionPreference='Stop';$inv=[Globalization.CultureInfo]::InvariantCulture
function I([object]$v){$x=0L;if($null -eq $v){return 0L};[Int64]::TryParse(([string]$v),[Globalization.NumberStyles]::Integer,$inv,[ref]$x)|Out-Null;return $x};function Delta4096([Int64]$a,[Int64]$b){return (($a-$b) -band 0x0FFF)}
if(-not(Test-Path -LiteralPath $CsvPath -PathType Leaf)){throw 'CSV absent.'};$rows=@(Import-Csv -LiteralPath $CsvPath);if($rows.Count -lt 3){throw 'CSV trop court.'};$props=@($rows[0].PSObject.Properties.Name);foreach($n in @('serial','type','transition_observer_contaminated','generated_presents','real_presents')){if($props -notcontains $n){throw ('Colonne requise absente: '+$n)}};$hasAttempts=($props -contains 'present_attempts');$hasSuccess=($props -contains 'present_successes')
$rawExtra=0L;$amb=0L;$excluded=0L;$gapEvents=0L;$cleanTransitions=0L;$focus=New-Object 'System.Collections.Generic.List[string]';$focus.Add('PTAR MARKER INTEGRITY V2');$focus.Add('VARIANT='+$Variant);$focus.Add('RUNTIME_SHA256='+$RuntimeSha256);$focus.Add('')
for($i=1;$i -lt $rows.Count;$i++){$cont=([string]$rows[$i].transition_observer_contaminated -eq '1');$d=Delta4096 (I $rows[$i].serial) (I $rows[$i-1].serial);if($cont){$excluded++;continue};$cleanTransitions++;if($d -lt 1 -or $d -gt 2048){$amb++;continue};if($d -gt 1){$gapEvents++;$rawExtra+=($d-1);$da='NA';$ds='NA';if($hasAttempts){$da=(I $rows[$i].present_attempts)-(I $rows[$i-1].present_attempts)};if($hasSuccess){$ds=(I $rows[$i].present_successes)-(I $rows[$i-1].present_successes)};$typed=((I $rows[$i].generated_presents)+(I $rows[$i].real_presents))-((I $rows[$i-1].generated_presents)+(I $rows[$i-1].real_presents));$focus.Add(('EVENT index={0} t_ms={1} serial={2}->{3} delta={4} extra={5} type={6}->{7} dwell_prev_ms={8} d_attempt={9} d_success={10} d_typed_present={11}' -f $i,$rows[$i].start_ms,$rows[$i-1].serial,$rows[$i].serial,$d,($d-1),$rows[$i-1].type,$rows[$i].type,$rows[$i-1].dwell_ms,$da,$ds,$typed))}}
$transitions=[Int64]($rows.Count-1);$typedDelta=((I $rows[-1].generated_presents)+(I $rows[-1].real_presents))-((I $rows[0].generated_presents)+(I $rows[0].real_presents));$successDelta=$typedDelta;if($hasSuccess){$successDelta=(I $rows[-1].present_successes)-(I $rows[0].present_successes)};$attemptDelta=-1L;if($hasAttempts){$attemptDelta=(I $rows[-1].present_attempts)-(I $rows[0].present_attempts)};$counterMissing=$successDelta-$transitions;if($counterMissing -lt 0){$counterMissing=0};$corroborated=[Int64][Math]::Min([double]$rawExtra,[double]$counterMissing);$markerOnly=$rawExtra-$corroborated;$failedAttempts='NA';if($attemptDelta -ge 0 -and $successDelta -ge 0){$failedAttempts=[string]($attemptDelta-$successDelta)};$alignment=$successDelta-$transitions;$class='CLEAN';if($amb -gt 0){$class='AMBIGUOUS_SERIAL_STEPS'}elseif($rawExtra -gt 0 -and $corroborated -eq 0 -and [Math]::Abs([double]$alignment) -le 2){$class='MARKER_SERIAL_ONLY_ADVANCE'}elseif($corroborated -gt 0){$class='POSSIBLE_VISIBLE_CONTENT_MISSED'}elseif($rawExtra -gt 0){$class='INDETERMINATE'}
$head=New-Object 'System.Collections.Generic.List[string]';function Add([string]$k,[object]$v){$head.Add($k+'='+[string]$v)};Add 'PTAR_MARKER_INTEGRITY' '2';Add 'VARIANT' $Variant;Add 'RUNTIME_SHA256' $RuntimeSha256;Add 'ROWS' $rows.Count;Add 'OBSERVED_TRANSITIONS' $transitions;Add 'CLEAN_TRANSITIONS' $cleanTransitions;Add 'OBSERVER_EXCLUDED_TRANSITIONS' $excluded;Add 'RAW_SERIAL_GAP_EVENTS' $gapEvents;Add 'RAW_SERIAL_EXTRA_ADVANCES' $rawExtra;Add 'AMBIGUOUS_SERIAL_STEPS' $amb;Add 'TYPED_PRESENT_DELTA' $typedDelta;Add 'PRESENT_SUCCESS_DELTA' $successDelta;Add 'PRESENT_ATTEMPT_DELTA' $(if($attemptDelta -ge 0){$attemptDelta}else{'NA'});Add 'ATTEMPT_MINUS_SUCCESS' $failedAttempts;Add 'PRESENT_SUCCESS_MINUS_OBSERVED' $alignment;Add 'PRESENT_CORROBORATED_MISSING_CONTENTS' $corroborated;Add 'MARKER_ONLY_EXTRA_ADVANCES' $markerOnly;Add 'CLASSIFICATION' $class;$all=New-Object 'System.Collections.Generic.List[string]';foreach($x in $head){$all.Add($x)};$all.Add('');foreach($x in $focus){$all.Add($x)};[IO.File]::WriteAllLines($OutPath,$all.ToArray(),(New-Object Text.UTF8Encoding($false)));Write-Host ('MARKER INTEGRITY: '+$class+' raw_extra='+$rawExtra+' corroborated='+$corroborated+' marker_only='+$markerOnly);exit 0
